%[text] # Motor Drive Unit - Simulation Case
%[text] ## Regenerative braking
%[text] Test that the motor can convert mechanical power to electric power.
model_name = "HarnessModel_MotorDriveUnit";
load_system(model_name)

HarnessSetup_MotorDriveUnit

set_param(model_name + "/Motor Drive Unit", ReferencedSubsystem = "MotorDriveUnit_BasicThermal_refsub")

set_param(model_name + "/Inputs", ReferencedSubsystem = "Inputs_MotorDriveUnit_RegenBrake_refsub")

% Initial conditions
initial.LoadInertiaSpeed = simscape.Value(0, "rpm");
initial.motorDriveUnit_RotorSpd_rpm = 0;
initial.ambientTemp_K = motorDriveUnit.ambientTemp_K;

sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime = "400");
%[text] Run simulation.
sim_out = sim(sim_in);
%[text] Visually inspect the result.
sim_data = extractTimetable(sim_out.logsout);

% Signal logging names in the model.
signal_names = [
  "Motor torque command"
  "Axle torque input"
  "Motor power rate"
  "Motor speed"
  "Motor temperature"
  "Battery power"
  "Battery current"
  "Battery voltage"
  ];

for idx = 1 : numel(signal_names) %[output:group:742a0a32]
  fig = SignalUtil1.plotTimedData(TimedData = sim_data, SignalName = signal_names(idx)); %[output:16cd9044] %[output:08da4ede] %[output:841be8bb] %[output:2df92ec4] %[output:7808ac1e] %[output:3c1c7550] %[output:74e2ffe1] %[output:034e48a7]
  fig.Position(4) = 200;  % height
end %[output:group:742a0a32]
